const { readProject } = require('../../projectReader')
const { merge } = require('../../merge')
const { srv4, enterpriseMessaging } = require('../../registries/mta')
const KymaTemplate = require('../kyma')

module.exports = class EnterpriseMessagingSharedTemplate extends require('../enterprise-messaging') {
  constructor(...args) {
    super(...args)
    this._name = 'enterprise-messaging-shared'
    this._kind = 'enterprise-messaging-amqp'
    this._vcap = 'enterprise-messaging'
    this._dirname = __dirname
    this._mta = enterpriseMessaging
  }

  static help() {
    return 'messaging via shared SAP Event Mesh'
  }

  async combine(facet) {
    const project = readProject(facet)
    const { affected, srv } = project

    if (affected('mta')) {
      const srvModule = srv4(srv.path)
      await merge(this._dirname, 'files', 'mta.yaml.hbs').into('mta.yaml', {
        project,
        additions: [srvModule, this._mta],
        relationships: [
          {
            insert: [this._mta, 'name'],
            into: [srvModule, 'requires', 'name']
          }
        ]
      })
    }

    if (affected('kyma')) {
      await merge(this._dirname, 'files/values.yaml').into('chart/values.yaml')
      await KymaTemplate.mergeDependency('service-instance', 'event-mesh')
    }

    if (affected('kyma') || affected('mta')) await merge(this._dirname, 'files/event-mesh.json.hbs').into('event-mesh.json', { project })
  }
}
